import React from 'react';
import clsx from 'clsx';
import styles from './GlowButton.module.scss';

interface Props {
  children: React.ReactNode;
  onClick?: () => void;
  className?: string;
  type?: 'button' | 'submit' | 'reset';
  variant?: 'sm' | 'success' | 'loading';
}

const GlowButton: React.FC<Props> = ({ children, onClick, className, type = 'button', variant }) => {
  const label = typeof children === 'string' ? children : '';
  return (
    <button
      type={type}
      className={clsx(styles.gb, variant && styles[variant], className)}
      onClick={onClick}
    >
      <span className={styles.text} data-text={label}>
        {children}
      </span>
    </button>
  );
};

export default GlowButton;
